function abidjanPromo(){const now=new Date(),parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Africa/Abidjan',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(now),vals={};parts.forEach(p=>vals[p.type]=p.value);const hour=Number(vals.hour),active=hour>=11&&hour<16,targetHour=active?16:(hour<11?11:35),target=new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth(),now.getUTCDate()+(targetHour===35?1:0),targetHour===35?11:targetHour,0,0)),left=Math.max(0,Math.ceil((target-now)/60000));return {active,left:Math.floor(left/60)+' h '+String(left%60).padStart(2,'0')+' min'}}
const DIGITAL_PACKS=[{id:'duo',name:'Pack Duo',badge:'2 SERVICES',discount:2,items:['spotify','crunchyroll']},{id:'triple',name:'Pack Triple',badge:'3 SERVICES',discount:2,items:['apple','spotify','crunchyroll']},{id:'four',name:'Pack de 4',badge:'4 SERVICES',discount:2,items:['apple','spotify','crunchyroll','iptv']},{id:'maxi',name:'Maxi pack',badge:'6 SERVICES',discount:2,items:['apple','spotify','crunchyroll','iptv','vpn','netflix']}];
function digitalPromoBanner(){return '<div class="digital-promo-banner" data-promo-banner><span class="promo-spark">✦</span><div><small>PROMO QUOTIDIENNE · 11 H–16 H</small><strong data-promo-status>Prix calculé automatiquement</strong><p data-promo-copy>Promo : 2 % de remise sur chaque pack, plus 1 000 FCFA par filleul qualifié (3 maximum).</p></div><b class="promo-clock" data-promo-clock>11:00–16:00</b></div>'}
function digitalServiceCard(p){return '<article class="digital-offer-card" data-brand="'+p.brand+'"><div class="digital-logo-frame"><img src="'+A+IMG[p.logo]+'" alt="Logo '+p.name+'" loading="lazy"></div><div class="digital-offer-copy"><span class="digital-offer-label">LOT INDIVIDUEL · 10 ACCÈS</span><h2>'+p.name+'</h2><p>'+p.subtitle+'</p><div class="digital-card-price"><strong data-individual-price="'+p.id+'">'+money(p.price)+' F</strong><small>prix fixe · 10 accès</small></div><div class="digital-quantity"><span>Nombre de lots</span><div><button type="button" data-offer-step="-1" data-service="'+p.id+'" aria-label="Retirer un lot">−</button><b data-offer-count="'+p.id+'">1</b><button type="button" data-offer-step="1" data-service="'+p.id+'" aria-label="Ajouter un lot">+</button></div></div><button class="button soft digital-select-button" disabled title="Le stock et la livraison des accès ne sont pas encore configurés">Stock à charger</button></div></article>'}
function digitalBundleCard(pack){const services=pack.items.map(id=>DIGITAL_PRODUCTS.find(p=>p.id===id)),sum=services.reduce((n,p)=>n+p.price,0),images=services.map(p=>'<span class="bundle-logo"><img src="'+A+IMG[p.logo]+'" alt="'+p.name+'" loading="lazy"></span>').join(''),names=services.map(p=>p.name).join(' + ');return '<article class="bundle-pack-card" data-pack-card="'+pack.id+'"><div class="bundle-pack-top"><span class="bundle-pack-badge">'+pack.badge+'</span><span class="bundle-pack-discount">−'+pack.discount+' %</span></div><h3>'+pack.name+'</h3><p class="bundle-pack-services">'+names+'</p><div class="bundle-pack-logos">'+images+'</div><div class="bundle-quantity"><span>Lots de 10 accès par service</span><div><button type="button" data-bundle-step="-1" data-pack="'+pack.id+'" aria-label="Retirer un lot">−</button><b data-bundle-count="'+pack.id+'">1</b><button type="button" data-bundle-step="1" data-pack="'+pack.id+'" aria-label="Ajouter un lot">+</button></div></div><div class="bundle-pack-prices"><strong class="bundle-total-price" data-pack-retail="'+pack.id+'">'+money(sum)+' F</strong></div><button class="button primary bundle-download" disabled title="Le stock et la livraison des accès ne sont pas encore configurés">Stock à charger</button></article>'}
function digitalResaleContent(){const bundles=DIGITAL_PACKS.map(digitalBundleCard).join(''),individuals=DIGITAL_PRODUCTS.map(digitalServiceCard).join('');return '<div class="digital-resale-content"><header class="resale-store-header"><div><span class="eyebrow">BOUTIQUE · ACHAT ET REVENTE</span><h1>Choisis tes packs <em>à revendre</em></h1><p>Chaque lot contient 10 accès par service. Les offres s’ouvriront dès que le stock réel et la remise sécurisée des accès seront configurés.</p></div><div class="resale-flow"><span><b>1</b> Achète</span><i>→</i><span><b>2</b> Récupère tes accès</span><i>→</i><span><b>3</b> Revends</span></div></header>'+digitalPromoBanner()+'<div class="digital-section-heading resale-packs-heading"><span><small>OFFRES DISPONIBLES</small><h2>Packs Duo, Triple, 4 et Maxi</h2></span><span class="section-count">Prix calculés automatiquement</span></div><div class="digital-bundle-grid">'+bundles+'</div><p class="digital-access-note">Chaque filleul qualifié donne 1 000 FCFA de réduction sur les packs (3 maximum), après sa première recharge confirmée de 3 000 FCFA minimum. Les offres individuelles sont exclues.</p><div class="digital-section-heading individual-heading"><span><small>OFFRES À L’UNITÉ</small><h2>Un service à la fois</h2></span><span class="section-count">10 accès par lot</span></div><div class="digital-offer-grid">'+individuals+'</div></div>'}
function qualifiedReferralCount(){return Math.min(3,Math.max(0,Math.floor(Number(window.KPYX_ACCOUNT?.qualifiedReferralCount||0))))}
function updateDigitalPricing(){const promo=abidjanPromo(),referralCredit=qualifiedReferralCount()*1000;document.querySelectorAll('[data-promo-status]').forEach(el=>el.textContent=promo.active?'PROMO · prix calculés automatiquement':'Prix calculé automatiquement');document.querySelectorAll('[data-promo-copy]').forEach(el=>el.textContent=promo.active?'Remise de 2 % appliquée au montant de chaque pack.':'Promotion de 2 % chaque jour, de 11 h à 16 h.');document.querySelectorAll('[data-promo-banner]').forEach(el=>el.classList.toggle('is-live',promo.active));DIGITAL_PRODUCTS.forEach(p=>document.querySelectorAll('[data-individual-price="'+p.id+'"]').forEach(el=>{const card=el.closest('.digital-offer-card'),count=Number(card.querySelector('[data-offer-count]').textContent||1);el.textContent=money(p.price*count)+' F';const pay=card.querySelector('.digital-select-button');if(pay){pay.dataset.totalPrice=p.price*count;pay.textContent='Payer '+money(p.price*count)+' F →'}}));DIGITAL_PACKS.forEach(pack=>{const card=document.querySelector('[data-pack-card="'+pack.id+'"]');if(!card)return;const qty=Number(card.querySelector('[data-bundle-count]').textContent||1),base=pack.items.reduce((n,id)=>n+DIGITAL_PRODUCTS.find(p=>p.id===id).price,0)*qty,rate=promo.active?pack.discount:0,cost=Math.max(0,Math.round(base*(100-rate)/100)-referralCredit);card.classList.toggle('is-promo',promo.active);card.querySelector('.bundle-pack-discount').textContent=promo.active?'PROMO':'';card.querySelector('[data-pack-retail]').textContent=money(cost)+' F';const pay=card.querySelector('.bundle-download');if(pay){pay.dataset.totalPrice=cost;pay.textContent='Payer '+money(cost)+' F · recevoir mes accès →'}})}
function startDigitalPurchase(amount){toast('Paiement de '+money(Number(amount||0))+' FCFA indisponible : aucun prestataire n’est connecté. Aucun accès n’est remis.')}
function money(n){return n.toLocaleString('fr-FR').replace(/\u202f/g,' ')}
function vipCatalogContent(){const bands=[['Espaces essentiels','L1–L3',0,3],['Espaces Pro','L4–L6',3,6],['Espaces Signature','L7–L8',6,8]];return `<div class="products-sticky"><div class="app-page-bar"><strong>Forfaits d’adhésion</strong><button class="owned-plans" data-go="my-products">${NAV_SVG.key} Mes forfaits <b>0</b></button></div><div class="products-title"><span><small>8 FORFAITS</small><h1>Forfaits <em>d’adhésion</em></h1></span></div><p class="products-sub">Choisissez un forfait. Les crédits indiqués sont cumulés pendant la durée, puis ajoutés au solde à l’échéance.</p><div class="howto"><div>${img('plans')}<small>01</small><span>Choisissez un forfait selon son prix et sa durée</span></div><div>${img('hourglass')}<small>02</small><span>Suivez la progression et les crédits bloqués</span></div><div>${img('cashout')}<small>03</small><span>À l’échéance, les crédits sont ajoutés au solde retirable</span></div></div></div>${bands.map(([heading,levels,start,end])=>`<section class="plan-band" data-band="${start}"><div class="band-heading"><h2>${heading}</h2><small>${levels}</small></div><div class="product-list">${PLANS.slice(start,end).map(([name,space,desc,price,daily,total,im,level,days],i)=>{const idx=start+i;return `<button class="actual-plan" data-plan-index="${idx}" data-range="${price<=2000?1:price<=10000?2:price<=50000?3:4}"><div class="plan-photo ${im}">${img(im)}<span class="level">${level}&nbsp; ${space}</span></div><div class="plan-card-content"><div class="plan-card-heading"><strong>${name}</strong><span class="round-arrow">${NAV_SVG.arrow}</span></div><p>${desc}</p><div class="plan-specs"><span><small>Prix</small><b>${money(price)} FCFA</b></span><span><small>Par jour</small><b class="credit">+${money(daily)} FCFA</b></span><span><small>Durée</small><b>${days} jours</b></span></div><div class="plan-total">Crédits à l’échéance <b>${money(total)} FCFA</b></div></div></button>`}).join('')}</div></section>`).join('')}`}
function products(){return dash("<div class='products-mode-shell'><section class='plan-mode-panel catalog-tabs'><div class='plan-mode-copy'><span class='eyebrow'>CATALOGUE KPYX</span><p>Choisis ton espace : forfaits VIP ou packs de comptes à revendre.</p></div><div class='plan-mode-switch' role='group' aria-label='Mode des offres'><button class='plan-mode' data-plan-mode='purchase' aria-pressed='false'>Achat · VIP</button><button class='plan-mode active' data-plan-mode='resale' aria-pressed='true'>Packs à revendre</button></div></section><section class='vip-purchase-content' hidden>"+vipCatalogContent()+"</section><section class='digital-resale-panel'>"+digitalResaleContent()+"</section></div>")}
function team(){const invite=[1000,2000,6000,12000,20000,60000],active=[5,10,30,60,100,300],network=[5000,10000,30000,50000,100000,300000,500000],volume=[500000,1000000,3000000,5000000,10000000,30000000,50000000];const tiers=(title,note,rewards,targets,label)=>`<section class="reward-group"><button class="reward-heading" data-toggle="${title==='Objectifs d’invitation'?'invite':'network'}"><span><strong>${title}</strong><small>${note}</small></span><b>0 / ${rewards.length}</b><i>⌄</i></button><div class="reward-list collapsed" data-rewards="${title==='Objectifs d’invitation'?'invite':'network'}">${rewards.map((reward,i)=>`<article class="reward-card"><div class="reward-top"><span class="tier-number">${i+1}</span><span class="tier-name">Palier ${i+1}</span><strong>${money(reward)} FCFA</strong><span class="locked">♙ &nbsp;Non atteint</span></div><div class="reward-target"><span>${label}</span><b>0&nbsp; / &nbsp;${money(targets[i])}${title==='Objectifs du réseau'?'':' membres'}</b></div><div class="progress-track"><i style="width:0%"></i></div></article>`).join('')}</div><button class="show-tiers" data-toggle="${title==='Objectifs d’invitation'?'invite':'network'}">Afficher les ${rewards.length} paliers　⌄</button></section>`;return dash(`<div class="team-sticky"><strong>Mon réseau</strong></div><div class="team-head"><div class="eyebrow" data-network-total-members>… DANS VOTRE RÉSEAU</div><h1>Mon <em>réseau</em></h1><img src="${A+IMG.network}" alt="" class="team-illustration"><p>Invitez des personnes avec votre code et réclamez les récompenses que vous débloquez.</p></div><section class="invite-card"><div class="invite-brand"><b>KPYX</b><span>PASS D'INVITATION</span><button data-action="copy-link" aria-label="Copier le lien">♧</button></div><div class="invite-code"><span>Code d'invitation</span><strong>${inviteCode()}</strong><button data-action="copy-invite" aria-label="Copier le code">⧉</button></div><div class="invite-link"><span>${inviteLink()}</span><button data-action="copy-link" aria-label="Copier le lien">↗</button></div><div class="commission-levels"><div><span class="level-dot"></span><small>1er</small><b>−1 000 F</b><span>Filleul qualifié</span></div><div><span class="level-dot"></span><small>2e</small><b>−1 000 F</b><span>Filleul qualifié</span></div><div><span class="level-dot"></span><small>3e</small><b>−1 000 F</b><span>Filleul qualifié</span></div></div></section><button class="bonus-info" data-action="toggle-bonus"><span class="bonus-icon">i</span><span><strong>Bonus de parrainage</strong><small>1 000 FCFA par filleul qualifié · 3 maximum</small></span><b>⌃</b></button><div class="bonus-detail"><p>Chacun des 3 premiers filleuls débloque <b>1 000 FCFA de réduction</b> sur les packs après une première recharge confirmée d’au moins <b>3 000 FCFA</b>.</p><p>La remise s’applique aux packs Duo, Triple, de 4 et Maxi. Elle ne s’applique pas aux offres individuelles.</p><p>La qualification doit être confirmée par le système de paiement avant que la remise soit appliquée.</p><div class="bonus-actions"><button class="button primary small" data-action="share-invite">Partager</button><button class="button soft small" data-action="copy-link">Copier le lien</button></div></div><section class="how-network"><div class="how-network-title"><div><small>COMMENT ÇA MARCHE ?</small><h2>Comment fonctionne le parrainage</h2><p>Partagez votre lien. Un filleul est qualifié après sa première recharge confirmée de 3 000 FCFA minimum.</p></div><button data-action="toggle-guide" aria-label="Fermer">×</button></div><div class="guide-steps" id="guide-steps">${[['invite','1','Partagez votre code d’invitation avec vos amis'],['growth','2','Vos amis s’inscrivent et souscrivent leur premier forfait'],['sparkle','3','Votre réduction apparaît après confirmation du dépôt admissible']].map(([im,n,t])=>`<div class="guide-step">${img(im)}<span>${n}</span><p>${t}</p></div>`).join('')}</div><div class="guide-rates"><p>Après une première recharge confirmée ≥ 3 000 FCFA <b>−1 000 FCFA sur les packs</b></p><p>Maximum <b>3 filleuls qualifiés</b>, soit 3 000 FCFA de réduction</p><p>Valable sur les packs ; <b>pas sur les achats individuels</b></p></div></section><section class="network-overview"><h2>Votre réseau en un coup d'œil</h2><article class="commission-card"><div><small>AVANTAGES DE PARRAINAGE</small><strong data-network-benefits-total>… FCFA</strong><span data-network-benefits-week>Cette semaine · … FCFA débloqués</span></div><button data-go="products">Utiliser mes réductions ↗</button></article><div class="network-stats"><article><strong data-network-total-members>…</strong><span>Total des membres</span></article><article><strong data-network-active-members title="Membres ayant une recharge confirmée au cours des 30 derniers jours">…</strong><span>Membres actifs · recharge confirmée sous 30 j</span></article><article><strong data-network-benefits-total>… FCFA</strong><span>Réductions de parrainage</span></article><article><strong data-network-subscriptions>… FCFA</strong><span>Recharges cumulées du réseau</span></article></div></section><section class="rewards-section"><h2>Récompenses</h2>${tiers('Objectifs d’invitation','Invitez des amis directs qui souscrivent un forfait. Chaque palier ne peut être réclamé qu’une fois.',invite,active,'Membres actifs')}${tiers('Objectifs du réseau','Total des recharges confirmées de votre réseau de niveaux 1 à 3. Chaque palier ne peut être réclamé qu’une fois.',network,volume,'Recharges du réseau')}</section><section class="network-members"><h2>Membres du réseau</h2><div class="member-level-tabs" role="tablist" aria-label="Membres du réseau">${['L1','L2','L3'].map((x,i)=>`<button role="tab" aria-selected="${i===0}" class="${i===0?'active':''}" data-level="${x}">${x}</button>`).join('')}</div><p class="level-caption">Niveau 1 (direct)</p><div class="member-empty">${img('door')}<p>Aucun membre pour le moment. Partagez votre code d'invitation pour développer votre réseau.</p></div></section>`)}
function community(){return dash(`${pageHead('Communauté','Les nouvelles de votre communauté KPYX.',button('Créer une publication','community-create','primary small'))}<div class="chips"><button class="chip active">Tout</button><button class="chip">Membres</button><button class="chip">Actualités</button></div><section class="glass-card big-empty">${img('community')}<h3>Bienvenue dans la communauté</h3><p>Les publications et actualités des membres apparaîtront ici.</p><button class="text-button" data-action="notice">Découvrir l’espace communauté</button></section>`)}
function listPage(){if(route==="my-products")return dash(`${pageHead("Mes forfaits","Retrouvez vos adhésions actives et leur échéance.")}<section id="vip-subscriptions-list" class="subscription-list"><div class="panel big-empty"><p>Chargement de vos forfaits…</p></div></section>`);let rows={'my-products':[['keycard','Mes forfaits','Vos adhésions actives apparaîtront ici.','Aucun forfait actif'],['plans','Découvrir les forfaits','Explorez les espaces et options disponibles.','']],'fund-flow':[['receipt','Mouvements du compte','Recharges, retraits et activités du compte.','Aucune activité récente'],['topup','Recharger mon solde','Ajoutez des fonds à votre compte membre.','']],'messages':[['inbox','Boîte de réception','Retrouvez les messages et annonces de KPYX.','Vous êtes à jour'], ''], 'withdraw-history':[['cashout','Retraits','Suivez vos demandes de retrait.','Aucun retrait pour le moment']],'recharge-history':[['topup','Recharges','Suivez vos opérations de recharge.','Aucune recharge pour le moment']]}[route]||[];let r=rows[0];return dash(`${pageHead(TITLES[route]||'Historique')}<section class="panel big-empty">${img(r[0])}<h3>${r[3]}</h3><p>${r[2]}</p>${r[1].includes('forfait')?button('Voir les forfaits →','go:products','primary small'):''}</section>`)}
function profile(){const rows=[['HISTORIQUE',[['receipt','Historique des recharges','recharge-history'],['cashout','Historique des retraits','withdraw-history']]],['ACTIVITÉS',[['checkin','Présence quotidienne','check-in']]],['SERVICES',[['help','Assistance','support'],['globe','À propos de KPYX','about']]],['PARAMÈTRES',[['shield','Changer le mot de passe','change-password'],['profile','Modifier le profil','edit-profile'],['phone','Obtenir l’application','app-download']]]];return dash(`<section class="account-hero"><div class="account-avatar profile-avatar"><img src="${profileAvatarUrl()}" alt="Photo de profil" data-profile-avatar></div><div class="account-identity"><h1 data-profile-username>Membre KPYX</h1><p data-profile-phone>—</p></div><button class="account-edit" data-go="edit-profile" aria-label="Modifier le profil"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="m16 5 3 3L8 19l-4 1 1-4Z"/><path d="m14 7 3 3"/></svg></button></section><section class="account-balance"><div class="account-balance-top"><span>Solde　<button class="text-button" data-action="toggle-balance">${eyeIcon()}</button></span><button class="active-plans" data-go="my-products"><b>0</b> Forfaits actifs</button></div><div class="account-amount"><strong id="balance">${money(balanceAmount)}</strong><span>FCFA</span></div><div class="account-actions"><button data-go="recharge" class="account-recharge">↙　Recharge</button><button data-go="withdraw">↗　Retrait</button><button data-go="fund-flow" aria-label="Historique">▤</button></div></section><div class="account-shortcuts">${[['keycard','Mes forfaits','my-products'],['growth','Activité','fund-flow'],['card','Compte de paiement','bank-card'],['inbox','Messages','messages']].map(([im,label,path])=>`<button data-go="${path}">${img(im)}<span>${label}</span></button>`).join('')}</div>${rows.map(([heading,items])=>`<section class="account-menu-group"><h2>${heading}</h2><div>${items.map(([im,label,path])=>`<button class="account-row" data-go="${path}">${img(im)}<span>${label}</span><b>›</b></button>`).join('')}</div></section>`).join('')}<button class="account-logout" data-action="logout">Se déconnecter</button>`)}
function escapeProfileText(value=''){return String(value).replace(/[&<>]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[char])).replace(/"/g,'&quot;').replace(/'/g,'&#39;')}
function profileAvatarUrl(profile=window.KPYX_PROFILE){const db=window.kpyxSupabase;if(profile?.avatar_path&&db)return db.storage.from('kpyx-avatars').getPublicUrl(profile.avatar_path).data.publicUrl;return './assets/kpyx-favicon.svg?v=profile-logo'}
function usernameNextChange(changedAt){if(!changedAt)return null;const date=new Date(changedAt),day=date.getUTCDate();date.setUTCDate(1);date.setUTCMonth(date.getUTCMonth()+1);const lastDay=new Date(Date.UTC(date.getUTCFullYear(),date.getUTCMonth()+1,0)).getUTCDate();date.setUTCDate(Math.min(day,lastDay));return date}
function editProfilePage(){const profile=window.KPYX_PROFILE||{},nextChange=usernameNextChange(profile.username_changed_at),locked=!!(profile.username&&nextChange&&Date.now()<nextChange.getTime());return dash(`${pageHead('Modifier le profil','Personnalisez les informations visibles sur votre compte.')}<section class="glass-card profile-edit-card"><div class="profile-edit-brand"><img src="./assets/kpyx-favicon.svg?v=profile-logo" alt="Logo KPYX"><div><strong>KPYX</strong><span>VOTRE PROFIL MEMBRE</span></div></div><form class="profile-edit-form" data-form="profile-edit"><div class="profile-photo-control"><img class="profile-photo-preview" data-profile-avatar src="${profileAvatarUrl(profile)}" alt="Photo de profil"><div><label class="button soft profile-photo-button" for="profile-photo">Choisir une photo</label><input class="visually-hidden" id="profile-photo" name="avatar" type="file" accept="image/jpeg,image/png,image/webp" data-profile-photo><small>JPG, PNG ou WebP · 8 Mo maximum</small></div></div><div class="field username-field"><label for="profile-username">Nom d’utilisateur</label><input class="input username-input" id="profile-username" name="username" value="${escapeProfileText(profile.username||'')}" minlength="3" maxlength="24" pattern="[A-Za-z0-9][A-Za-z0-9._-]{2,23}" autocomplete="username" autocapitalize="none" spellcheck="false" ${locked?'readonly':''} required><small class="username-hint" data-username-status>${locked?`Modifiable à partir du ${nextChange.toLocaleDateString('fr-FR')}.`:'Ce nom unique est celui affiché sur votre profil.'}</small></div><div class="profile-name-grid"><div class="field"><label for="profile-first-name">Prénom</label><input class="input" id="profile-first-name" name="first_name" value="${escapeProfileText(profile.first_name||'')}" maxlength="80" autocomplete="given-name" placeholder="Votre prénom"></div><div class="field"><label for="profile-last-name">Nom de famille</label><input class="input" id="profile-last-name" name="last_name" value="${escapeProfileText(profile.last_name||'')}" maxlength="80" autocomplete="family-name" placeholder="Votre nom"></div></div><div class="field"><label for="profile-birthday">Date de naissance</label><input class="input" id="profile-birthday" name="date_of_birth" type="date" max="${new Date().toISOString().slice(0,10)}" value="${escapeProfileText(profile.date_of_birth||'')}" autocomplete="bday"></div><div class="wallet-note profile-username-rule"><b>Changement du nom d’utilisateur</b><span>Vous pouvez modifier les autres informations à tout moment. Après un changement de nom d’utilisateur, le prochain sera possible un mois plus tard.</span></div><button class="button primary profile-save" type="submit">Enregistrer mon profil →</button></form></section>`)}
function showProfileAvatar(src){document.querySelectorAll('[data-profile-avatar]').forEach(image=>{image.src=src})}
async function loadProfilePage(){const db=window.kpyxSupabase;if(!db||!['profile','edit-profile'].includes(route))return;const currentRoute=route;const {data:{user}}=await db.auth.getUser();if(!user||route!==currentRoute)return;const {data,error}=await db.from('profiles').select('username,first_name,last_name,date_of_birth,avatar_path,username_changed_at').eq('id',user.id).maybeSingle();if(error){console.error('KPYX profile load failed:',error.message);if(route==='edit-profile')toast('Le profil ne peut pas être chargé. Vérifiez la configuration du compte.');return}window.KPYX_PROFILE=data||{};const username=data?.username||user.user_metadata?.username||'Membre KPYX',name=document.querySelector('[data-profile-username]'),phone=document.querySelector('[data-profile-phone]');if(name)name.textContent=username;if(phone)phone.textContent=user.phone||user.user_metadata?.phone_e164||'';showProfileAvatar(profileAvatarUrl(data));if(route==='edit-profile'){const form=document.querySelector('[data-form="profile-edit"]');if(form){form.elements.username.value=data?.username||'';form.elements.first_name.value=data?.first_name||'';form.elements.last_name.value=data?.last_name||'';form.elements.date_of_birth.value=data?.date_of_birth||'';const next=usernameNextChange(data?.username_changed_at),locked=!!(data?.username&&next&&Date.now()<next.getTime());form.elements.username.readOnly=locked;const hint=form.querySelector('[data-username-status]');if(hint)hint.textContent=locked?`Modifiable à partir du ${next.toLocaleDateString('fr-FR')}.`:'Ce nom unique est celui affiché sur votre profil.';showProfileAvatar(profileAvatarUrl(data))}}}function operation(kind){const rec=kind==='recharge',min=rec?3000:1200,max=90071992547409,presets=rec?[3000,8000,15000,30000,60000,150000]:[1200,2000,3000,5000,10000],title=rec?'Recharge':'Retrait';const methods=[['orange','Orange Money'],['mtn','MTN Money'],['wave','Wave'],['moov','Moov Money']];return dash(`<div class="wallet-head"><button class="support-back" data-go="profile" aria-label="Retour">←</button><div><span class="eyebrow">PORTEFEUILLE</span><h1>${title}</h1></div><button class="wallet-history" data-go="${rec?'recharge-history':'withdraw-history'}">Historique ↗</button></div><form class="glass-card form-panel wallet-form" data-form="operation" data-kind="${kind}"><div class="wallet-balance"><span>${rec?'Solde du membre':'Disponible pour un retrait'}</span><strong id="balance">${money(balanceAmount)} <small>FCFA</small></strong><button type="button" data-action="toggle-balance">${eyeIcon()}</button></div><div class="wallet-input-heading"><label for="wallet-amount">${rec?'Montant':'Montant du retrait'}</label><span>Min. ${money(min)} · Max. ${money(max)} FCFA</span></div><div class="wallet-amount-input"><input id="wallet-amount" name="amount" class="input" type="number" min="${min}" max="${max}" step="100" placeholder="Saisissez le montant" required><b>FCFA</b></div><div class="preset-title">Montants rapides</div><div class="chips wallet-presets">${presets.map(v=>`<button class="chip" type="button" data-amount="${v}">${money(v)}</button>`).join('')}</div><div class="wallet-section-title">${rec?'Choisissez votre mode de paiement':'Destination du retrait'}</div><div class="payment-methods payment-method-list">${methods.map(([id,label],i)=>`<button type="button" class="payment-method ${i===0?'active':''}" data-method="${id}" aria-pressed="${i===0}"><i>${id==='wave'?'◉':id==='orange'?'◌':id==='mtn'?'●':id==='moov'?'◆':'▣'}</i><span><b>${label}</b></span><b>${i===0?'✓':'○'}</b></button>`).join('')}</div>${rec?`<input type="hidden" name="method" value="orange"><div class="wallet-note"><b>Recharge sécurisée</b><span>Montant minimum : 3 000 FCFA. Votre solde et la roue sont mis à jour après confirmation du paiement.</span></div><div class="wallet-summary"><span>Vous allez recharger</span><strong id="wallet-summary">— FCFA</strong></div>`:`<label class="field payout-destination"><span>Numéro Mobile Money ou identifiant Djamo</span><input class="input" name="destination" type="text" autocomplete="tel" minlength="6" maxlength="80" placeholder="Ex. +225 07 00 00 00 00" required></label><input type="hidden" name="method" value="orange"><div class="withdraw-summary"><div><span>Frais de retrait (7 %)</span><b id="withdraw-fee">— FCFA</b></div><div><span>Vous recevrez</span><strong id="withdraw-net">— FCFA</strong></div></div><div class="wallet-note"><b>Retrait manuel</b><span>Votre demande reste en attente jusqu’à son traitement. Vérifiez soigneusement la destination avant validation.</span></div>`}<button class="button primary wallet-submit" type="submit">${rec?'Continuer vers le paiement':'Demander le retrait'} →</button></form>`)}
function lottery(){const prizes=[100,200,500,1000,2000,5000,10000,20000];return dash(`${pageHead('Roue de la chance','La roue se débloque après confirmation d’une recharge de 3 000 FCFA ou plus.',`<button class="owned-plans" data-go="fund-flow">Mes gains&nbsp; 0</button>`)}<section class="lottery-screen"><div class="lottery-caption">${img('wheel','lottery-source-icon')}<span class="badge">AVANTAGE ROOFTOP</span><h2>Tournez pour gagner<br><em>des lots membres</em></h2><p>Des prix en argent pour les membres · Chaque tour est gagnant</p></div><div class="wheel-status"><span class="pulse-dot"></span><span id="wheel-status">Recharge confirmée requise · 3 000 FCFA min.</span><button class="text-button" data-action="show-wheel-rules">Règles</button></div><div class="wheel-stage"><div class="wheel-pointer"><svg viewBox="0 0 24 32"><path d="M12 31 1 3a1.5 1.5 0 0 1 2-1.8L12 5l9-3.8A1.5 1.5 0 0 1 23 3Z"/></svg></div><div class="wheel-disk" id="wheel-disk"><div class="wheel-labels">${prizes.map(x=>`<span>${money(x)}</span>`).join('')}</div><div class="wheel-hub"></div></div><div class="wheel-center"></div></div><button class="button primary spin-button" data-action="spin">TOURNER</button><p class="spin-note">Tour disponible uniquement après confirmation d’une recharge de 3 000 FCFA minimum.</p><div class="lottery-inline-actions"><button data-action="show-wheel-rules">Comment jouer ?</button><button data-go="products">Choisir un forfait ↗</button></div></section><section class="lottery-ladder"><div><h2>Sur la roue</h2><p>Des prix en argent, versés sur votre portefeuille lorsque vous les réclamez.</p></div><div class="prize-grid">${prizes.slice().reverse().map((x,i)=>`<article class="prize-tile"><span>${i===0?'GAIN MAXIMAL':'LOT MEMBRE'}</span><strong>${money(x)} <small>FCFA</small></strong></article>`).join('')}</div></section><section class="panel lottery-history section"><div class="panel-title">Mes tours <span class="badge">HISTORIQUE</span></div><p>Chaque tour et son résultat apparaîtront ici.</p><div id="spin-history"><div class="big-empty">${img('wheel')}<h3>Aucun tour pour le moment</h3><p>Vos résultats de la roue apparaîtront ici.</p></div></div></section><section class="lottery-winners panel section"><div class="panel-title">Derniers gagnants <span class="live-badge"><i></i> EN DIRECT</span></div><div class="winner-row"><span class="winner-avatar">A</span><span><b>Membre KPYX</b><small>vient de tourner la roue</small></span><strong>+ 500 FCFA</strong></div><div class="winner-row"><span class="winner-avatar">K</span><span><b>Membre KPYX</b><small>a remporté un lot membre</small></span><strong>+ 1 000 FCFA</strong></div><div class="winner-row"><span class="winner-avatar">M</span><span><b>Membre KPYX</b><small>a remporté un lot membre</small></span><strong>+ 200 FCFA</strong></div></section>`)}
function localKpyxDate(){const p=new Intl.DateTimeFormat('en',{timeZone:'Africa/Abidjan',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).reduce((o,x)=>(o[x.type]=x.value,o),{});return p.year+'-'+p.month+'-'+p.day}
function checkInPage(){return dash(pageHead('Présence quotidienne','Pointez chaque jour pour recevoir 100 FCFA.')+'<section class="glass-card attendance-card"><div class="attendance-emblem">'+img('checkin')+'</div><span class="eyebrow">RÉCOMPENSE DU JOUR</span><h2>Votre présence compte</h2><p>Validez votre présence une fois par jour et recevez immédiatement <strong>100 FCFA</strong> sur votre solde.</p><div class="attendance-reward"><span>Bonus aujourd’hui</span><strong>+100 <small>FCFA</small></strong></div><button class="button primary attendance-claim" data-action="claim-attendance">Pointer ma présence →</button><small class="attendance-status" data-attendance-status>Le pointage est disponible chaque jour.</small></section>')}
async function loadDailyAttendance(){const button=document.querySelector('[data-action="claim-attendance"]'),status=document.querySelector('[data-attendance-status]'),db=window.kpyxSupabase;if(!button||!db)return;const {data:{user}}=await db.auth.getUser();if(!user){button.disabled=true;if(status)status.textContent='Connectez-vous pour pointer votre présence.';return}const {data,error}=await db.from('daily_attendance_claims').select('id').eq('user_id',user.id).eq('attendance_date',localKpyxDate()).maybeSingle();if(error){console.error('Attendance status unavailable:',error.message);if(status)status.textContent='Rechargez la page pour actualiser votre pointage.';return}if(data){button.disabled=true;button.textContent='Présence validée aujourd’hui ✓';button.classList.add('attendance-done');if(status)status.textContent='Vos 100 FCFA ont été ajoutés à votre solde.'}}
async function loadGiftRedemptions(){const box=document.querySelector('#gift-redemption-history'),db=window.kpyxSupabase;if(!box||!db)return;const {data,error}=await db.rpc('kpyx_my_gift_redemptions');if(error){console.error('Gift history unavailable:',error.message);return}if(!data||!data.length)return;box.replaceChildren();for(const item of data){const row=document.createElement('article');row.className='gift-redemption-row';const name=document.createElement('strong');name.textContent=item.code;const amount=document.createElement('span');amount.textContent='+'+new Intl.NumberFormat('fr-FR').format(item.amount_xof)+' FCFA';const date=document.createElement('small');date.textContent=new Intl.DateTimeFormat('fr-FR',{dateStyle:'medium'}).format(new Date(item.redeemed_at));row.append(name,amount,date);box.append(row)}}
function giftCodePage(){return dash(`${pageHead('Code cadeau','Échangez un code contre des crédits.')}<section class="gift-code-card"><div class="gift-code-art">${img('gift')}</div><span class="eyebrow">AVANTAGE ASSISTANCE</span><h2>Saisissez votre code cadeau</h2><p>Vous avez reçu un code lors d’un événement ou de la communauté ? Saisissez-le pour ajouter le crédit à votre solde.</p><form data-form="gift-redeem"><label for="gift-code-input">Code cadeau</label><div class="gift-input-row"><input id="gift-code-input" class="input" placeholder="Saisissez le code" autocomplete="off" required><button type="button" data-action="clear-gift" aria-label="Effacer le code">×</button></div><small>Tapez ou collez le code que vous avez reçu.</small><button class="button primary" type="submit">Utiliser le code →</button></form></section><section class="gift-records panel section"><div class="panel-title">Mes codes utilisés</div><div id="gift-redemption-history" class="gift-redemption-history"><div class="big-empty">${img('gift')}<h3>Aucun code utilisé pour le moment</h3></div></div></section>`)}

function escapeNotificationText(value){return String(value||'').replace(/[&<>\"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[char]))}
function setNotificationCount(count){document.querySelectorAll('[data-notification-count]').forEach(badge=>{const n=Math.max(0,Number(count)||0);badge.textContent=n>9?'9+':String(n);badge.hidden=n===0;badge.setAttribute('aria-label',n?(n+' notification'+(n>1?'s':'')+' non lue'+(n>1?'s':'')):'Aucune notification non lue')})}
async function refreshNotificationCount(db=window.kpyxSupabase){if(!db)return;const {count,error}=await db.from('notifications').select('id',{count:'exact',head:true}).is('read_at',null);if(!error)setNotificationCount(count||0)}
async function loadNotificationsPage(){const box=document.querySelector('#notification-list'),db=window.kpyxSupabase;if(!box||!db)return;const {data,error}=await db.from('notifications').select('id,title,body,kind,read_at,created_at').order('created_at',{ascending:false}).limit(50);if(error){box.innerHTML='<p class="sub">Impossible de charger les notifications. Réessayez.</p>';return}if(!data?.length){box.innerHTML='<div class="big-empty"><h3>Pas encore de notification</h3><p>Les nouveaux messages apparaîtront ici.</p></div>';setNotificationCount(0);return}box.innerHTML=data.map(n=>'<button type="button" class="notification-item '+(n.read_at?'is-read':'is-unread')+'" data-notification-id="'+escapeNotificationText(n.id)+'"><span class="notification-dot" aria-hidden="true"></span><span class="notification-copy"><strong>'+escapeNotificationText(n.title)+'</strong><span>'+escapeNotificationText(n.body)+'</span><small>'+new Intl.DateTimeFormat('fr-FR',{dateStyle:'medium',timeStyle:'short'}).format(new Date(n.created_at))+'</small></span></button>').join('');refreshNotificationCount(db)}
