document.addEventListener('submit',async e=>{const form=e.target.closest('[data-form="profile-edit"]');if(!form)return;e.preventDefault();const submit=form.querySelector('[type="submit"]'),db=window.kpyxSupabase;submit.disabled=true;try{if(!db){toast('Connexion au profil indisponible. Réessayez.');return}const {data:{user}}=await db.auth.getUser();if(!user){go('login');return}const username=form.elements.username.value.trim(),current=window.KPYX_PROFILE?.username||'';if(!/^[A-Za-z0-9][A-Za-z0-9._-]{2,23}$/.test(username)){toast('Choisissez un nom de 3 à 24 caractères.');return}if(username!==current){const {data:available,error}=await db.rpc('is_kpyx_username_available',{p_username:username});if(error){toast('La vérification du nom est indisponible. Réessayez.');return}if(!available){toast('Ce nom d’utilisateur est déjà utilisé. Entrez-en un autre.');form.elements.username.focus();return}}let avatarPath=window.KPYX_PROFILE?.avatar_path||null;const file=form.elements.avatar.files?.[0];if(file){const image=await imageAsWebp(file),path=user.id+'/avatar.webp',{data:uploaded,error:uploadError}=await db.storage.from('kpyx-avatars').upload(path,image,{upsert:true,contentType:'image/webp',cacheControl:'3600'});if(uploadError)throw uploadError;avatarPath=uploaded.path}const {error}=await db.rpc('update_my_profile',{p_username:username,p_first_name:form.elements.first_name.value.trim(),p_last_name:form.elements.last_name.value.trim(),p_date_of_birth:form.elements.date_of_birth.value||null,p_avatar_path:avatarPath});if(error){const message=error.message||'';if(/username_taken|duplicate key|unique/i.test(message))toast('Ce nom d’utilisateur est déjà utilisé. Entrez-en un autre.');else if(/username_cooldown/i.test(message))toast('Vous pourrez changer de nom d’utilisateur un mois après votre dernier changement.');else if(/date_of_birth_invalid/i.test(message))toast('La date de naissance ne peut pas être dans le futur.');else if(/function .* does not exist|schema cache/i.test(message))toast('La mise à jour du profil attend l’installation de la migration Supabase.');else throw error;return}await syncKpyxAccount();route='profile';paintRoute();toast('Profil mis à jour.')}catch(error){console.error('KPYX profile update failed:',error?.message||'unknown error');toast('Impossible d’enregistrer le profil. Vérifiez votre photo et réessayez.')}finally{submit.disabled=false}},true);document.addEventListener('input',e=>{if(e.target.matches('[data-resale-price]'))updateDigitalPricing()});
