function updateWalletPreview(){const form=document.querySelector('.wallet-form');if(!form)return;const amount=Number(form.querySelector('[name=amount]')?.value||0);if(form.dataset.kind==='recharge'){const value=document.querySelector('#wallet-summary');if(value)value.textContent=amount?money(amount)+' FCFA':'— FCFA'}else{const fee=document.querySelector('#withdraw-fee'),net=document.querySelector('#withdraw-net');if(fee)fee.textContent=amount?money(Math.round(amount*.07))+' FCFA':'— FCFA';if(net)net.textContent=amount?money(amount-Math.round(amount*.07))+' FCFA':'— FCFA'}}
document.addEventListener('submit',async e=>{const form=e.target.closest('[data-form="operation"]');if(!form)return;e.preventDefault();const db=window.kpyxSupabase;if(!db){toast('Service de compte indisponible. Réessayez plus tard.');return}const {data:{session}}=await db.auth.getSession();if(!session){go('login');return}if(form.dataset.kind==='withdraw'){try{await settleMaturedVipCredits(session,true);await syncKpyxAccount()}catch(error){toast(error.message||'Impossible d’actualiser le solde. Réessayez.');return}}const amount=Number(form.querySelector('[name=amount]').value),method=form.querySelector('[name=method]').value,endpoint=form.dataset.kind==='recharge'?'/api/jeko/create-payment':'/api/withdrawals',payload=form.dataset.kind==='recharge'?{amount,paymentMethod:method}:{amount,method,account:form.querySelector('[name=destination]').value.trim()},submit=form.querySelector('[type=submit]');submit.disabled=true;try{const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${session.access_token}`},body:JSON.stringify(payload)}),result=await response.json();if(!response.ok)throw new Error(result.error||'Opération impossible.');if(form.dataset.kind==='recharge'){location.assign(result.redirectUrl);return}await syncKpyxAccount();toast('Demande envoyée. Elle est en attente de traitement.');go('withdraw-history')}catch(error){toast(error.message)}finally{submit.disabled=false}},true);
document.addEventListener('input',e=>{if(e.target.matches('#wallet-amount'))updateWalletPreview()});
document.addEventListener('click',async e=>{const quick=e.target.closest('[data-quick-question]');if(quick){window.KPYXAskSupport?.(quick.dataset.quickQuestion);return}const method=e.target.closest('[data-method]');if(method){document.querySelectorAll('[data-method]').forEach(x=>{x.classList.toggle('active',x===method);x.setAttribute('aria-pressed',String(x===method));const mark=x.querySelector(':scope > b:last-child');if(mark)mark.textContent=x===method?'✓':'○'});const hidden=document.querySelector('.wallet-form [name=method]');if(hidden)hidden.value=method.dataset.method;return}const action=e.target.closest('[data-action]')?.dataset.action;if(action==='claim-attendance'){const db=window.kpyxSupabase,button=e.target.closest('[data-action]'),status=document.querySelector('[data-attendance-status]');if(!db){toast('Service de présence indisponible. Réessayez.');return}button.disabled=true;try{const {data:{user}}=await db.auth.getUser();if(!user){go('login');return}const {data,error}=await db.rpc('kpyx_claim_daily_attendance');if(error)throw error;if(!data||!data.claimed){button.textContent='Présence déjà validée aujourd’hui ✓';button.classList.add('attendance-done');if(status)status.textContent='Vous avez déjà reçu les 100 FCFA du jour.';toast('Votre présence a déjà été enregistrée aujourd’hui.');return}await syncKpyxAccount();button.textContent='Présence validée · +100 FCFA ✓';button.classList.add('attendance-done');if(status)status.textContent='100 FCFA ont été ajoutés à votre solde.';toast('Présence validée : +100 FCFA !')}catch(error){console.error('Attendance claim failed:',error&&error.message||'unknown error');button.disabled=false;toast('Pointage impossible pour le moment. Vérifiez votre connexion et réessayez.')}return}else if(action==='clear-gift'){const input=document.querySelector('#gift-code-input');if(input)input.value=''}else if(action==='claim-prize'){document.querySelector('.wheel-result')?.remove();toast('Résultat conservé dans cet aperçu local.')}else if(action==='show-wheel-rules'){document.querySelector('.wheel-rules-modal')?.remove();document.body.insertAdjacentHTML('beforeend','<div class="announcement-backdrop visible wheel-rules-modal"><section class="announcement wheel-result-card"><button class="icon-button detail-close" data-action="close-rules">×</button><span class="badge">RÈGLES</span><h2>Règles de la roue de la chance</h2><div class="announcement-copy"><p>Souscrivez un forfait pour débloquer des tours. Un tour est aussi gagné lorsqu’un ami invité souscrit son premier forfait.</p><p>Certains gains peuvent nécessiter des amis actifs. Chaque résultat apparaît dans votre historique.</p></div><button class="button primary" data-action="close-rules">Compris</button></section></div>')}else if(action==='close-rules'){document.querySelector('.wheel-rules-modal')?.remove()}else if(action==='contact-telegram'||action==='contact-whatsapp'){const url=action==='contact-telegram'?'https://t.me/kpyx_chanel_officiel':'https://chat.whatsapp.com/I6IqBpvABhdBe6lLynimmy?s=cl&p=i&mlu=4&ilr=4&iam=2';window.open(url,'_blank','noopener,noreferrer')}else if(action==='request-human'){if(route!=='support'){go('support')}else toast('Écrivez votre demande dans la messagerie assistance.')}});
