document.addEventListener('click',async e=>{const item=e.target.closest('[data-notification-id]');const markAll=e.target.closest('[data-action="notifications-read-all"]');if(!item&&!markAll)return;const db=window.kpyxSupabase;if(!db){toast('Service de notifications indisponible.');return}try{if(markAll){const {error}=await db.rpc('kpyx_mark_all_notifications_read');if(error)throw error;document.querySelectorAll('.notification-item.is-unread').forEach(row=>{row.classList.remove('is-unread');row.classList.add('is-read')})}else if(item.classList.contains('is-unread')){const {error}=await db.rpc('kpyx_mark_notification_read',{p_notification_id:item.dataset.notificationId});if(error)throw error;item.classList.remove('is-unread');item.classList.add('is-read')}await refreshNotificationCount(db)}catch(error){console.error('Notification update failed:',error&&error.message||'unknown error');toast('La mise à jour de la notification a échoué. Réessayez.')}});
document.addEventListener('submit',async e=>{const form=e.target.closest('[data-form="gift-redeem"]');if(!form)return;e.preventDefault();e.stopImmediatePropagation();const db=window.kpyxSupabase,submit=form.querySelector('[type="submit"]'),code=form.querySelector('#gift-code-input')?.value.trim();if(!db){toast('Service de codes cadeaux indisponible. Réessayez.');return}submit.disabled=true;try{const {data:{user}}=await db.auth.getUser();if(!user){go('login');return}const {data,error}=await db.rpc('kpyx_redeem_gift_code',{p_code:code});if(error)throw error;if(!data||!data.redeemed){const messages={invalid:'Code invalide, expiré ou épuisé.',already_used:'Vous avez déjà utilisé ce code. Il ne peut être utilisé qu’une fois par compte.',exhausted:'Ce code a atteint sa limite d’utilisations.',topup_required:'Rechargez au moins 3 000 FCFA avant d’utiliser un code cadeau.'};toast(messages[data&&data.reason]||'Ce code ne peut pas être utilisé.');return}await syncKpyxAccount();await loadGiftRedemptions();form.reset();toast('Code accepté : +'+new Intl.NumberFormat('fr-FR').format(data.amount_xof)+' FCFA ajoutés à votre solde.')}catch(error){console.error('Gift redemption failed:',error&&error.message||'unknown error');toast('Impossible d’utiliser ce code pour le moment. Réessayez.')}finally{submit.disabled=false}},true);
